-- ========================================================
-- Smart Job Finder Database Schema & Seed Data (110+ Companies)
-- ========================================================

CREATE DATABASE IF NOT EXISTS smartjobfinder;
USE smartjobfinder;

-- 1. Users Table (Job Seekers)
CREATE TABLE IF NOT EXISTS users (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    email VARCHAR(150) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 2. Admins Table (Platform Administrators)
CREATE TABLE IF NOT EXISTS admins (
    id INT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(100) NOT NULL UNIQUE,
    email VARCHAR(150) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 3. Companies Table (Job Openings)
CREATE TABLE IF NOT EXISTS companies (
    id INT AUTO_INCREMENT PRIMARY KEY,
    company_name VARCHAR(100) NOT NULL UNIQUE,
    skills VARCHAR(300) NOT NULL,
    role VARCHAR(150) NOT NULL,
    salary VARCHAR(50) NOT NULL,
    experience VARCHAR(50) DEFAULT '0-2',
    description TEXT,
    logo VARCHAR(255) NOT NULL,
    apply_url VARCHAR(300) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE'
);

-- 4. Seed Platform Admin
ON DUPLICATE KEY UPDATE password='12345';

-- 5. Seed Default Test User
ON DUPLICATE KEY UPDATE email=email;

-- 6. Seed 110+ Verified Company Job Openings
ON DUPLICATE KEY UPDATE
    skills = VALUES(skills),
    role = VALUES(role),
    salary = VALUES(salary),
    experience = VALUES(experience),
    description = VALUES(description),
    logo = VALUES(logo),
    apply_url = VALUES(apply_url),
    status = VALUES(status);
